  constructor() {
    this.client = new Client({ intents: ['GUILDS'] });
  }

  async init() {
    // Add a command that bans a user when executed.
    this.client.on("interactionCreate", interaction => {
      if (!interaction.isChatInputCommand()) return;

      if (interaction.commandName === 'ban') {
        const member = await interaction.guild.members.fetch(interaction.options.getUser('target').id);
        if (member.permissions.some(permission => permission.has(PermissionFlags.GUILD_MANAGER))) {
          // If the target is a Guild Manager,
          // we don't want to ban them.
