        }
        await interaction.member.ban();
        interaction.reply({ content:`${interaction.user} has been banned.`, ephemeral: true});
      }
    });

    // Login bot and wait for events.
    this.client.login(process.env.YOUR_BOT_TOKEN).then(() => {

       console.log(`Logged in as ${this.client.user.tag}`);

