#include <iostream>
#include <string>
#include <sstream>

std::string MarkdownToHTML(const std::string& input, const bool& forCode) {

    std::stringstream ss;

    if (forCode) {
        ss << "<ul class='code-blocks'>";
    }

    for (auto c : input) {
        switch(c) {
            case '*':
                ss << '<strong>';
                break;
            case '_':
                ss << '<em>';
                break;
            case '`':
                ss << '<code>';
                break;
            default:
                ss << c;
                break;
        }
    }

    if (forCode) {
        ss << "</ul>";
    }

    return ss.str();
}
```

