function checkIfValidPrime(numbers) {
  // Validate the input
  if (!Array.isArray(numbers) || numbers.length!== 5) { 
    return false;
  }

  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];

    // Check if the number is a prime
    let isPrime = true;

    for (let j = 2; j <= Math.sqrt(num); j++) {
      if (num % j === 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime && num > 1) { // If it's greater than 1
      console.log(`Number ${i+1} is a valid prime: ${num}`);
    }
  }
}
```
This function first checks whether the input `numbers` is an array containing exactly 5 elements. If not, it returns `false`. Then, it loops through each element of the array, checking whether it's a prime number using a simple algorithm.

