```latex
\documentclass{article}
\usepackage[utf8]{inputenc}

% package for generating table of content
\usepackage{xltabular, makeidx, idxlayout}

%\providecommand{\printindex}[1]{} % For XeLaTeX

% Define custom TOC layout
\newlength{\maxtocdepthwidth}  % New length for maximum depth width
\setlength{\maxtocdepthwidth}{0.4in}   % New value for TOC depth width (adjust as needed)
\def\showcontents#1{
  \ifnum #1>1 % If more than one level is shown
    \par\kern 3pt\noindent\textbf{Contents:} & \\
  \fi
  \ifnum #1<2 % If only first level is shown
    \begin{tabularx}{\textwidth}{@{}lL@{}}
      \footnotesize\textit{Introduction} &
      \small
      \rule{0cm}{0.5em}\\
      Section \ref{sec:first}
      \small
      \rule{0cm}{0.5em}\\
      Section \ref{sec:second}
      \small
      \rule{0cm}{0.5em}\\
    \end{tabularx}
  \else
    \vskip12pt\hrule\vskip12pt          % Line after title
    \begin{textblock*}{\maxtocdepthwidth}(0cm,-7em) % Place in TOC column of main text
      Contents:\hfil\break\null
    \end{textblock*}
    \addtocontents{toc}{\protect\clearpage}% Reset counter for page numbering
  \fi
}

% Generate index file
\makeatletter
\renewcommand*\section{\@startsection{section}{1}{-1em}{0pt plus 1pt minus -.2pt}{\normalfont\sbf}}
\renewcommand*\subsection{\@startsection{subsection}{2}{-1em}{0pt plus.8pt minus -.2pt}{\normalfont\sbf}}
\renewcode\normalsfcodesection
\renewcode\normalsfcodeheadingsection
\makeatother
\makeindex[\submit]
\AtBeginDocument{%
  \RequirePackage{etoolbox}
  \makeatletter
  \@begindocumenthook{%
    \expandafter\IndexStyle\@gobble
    \doIndexHeadings{all}%
    \doIndexSections{n, s}%
    \dorenderIndex{\string\index}\doPrintIndex{main}%
  }%
  \makeatother
}

% Start document
\begin{document}
  \title{Sample Document with TOC and Index}
  \author{Your Name}
  \date{Today's date}

  \maketitle

  \showcontents{1}

  \tableofcontents

  \clearpage

  \begin{abstract}
     This is a sample abstract.
  \end{abstract}

  \section{Section One}
    This is the content of section one.

  \section{Section Two}
    This is the content of section two.

  \section{Index Section}
    Here's where we create an index for this document.

  \bibliography{myrefs} % Add bibliography if necessary

% Print index at end of the document
\appendix
\phantomsection
\addcontentsline{toc}{chapter}{Appendices}
\makeindex

\printindex

\end{document}
```

