public class PowerOfThree {

    public boolean isPowerOfThree(int n) {
        // If n is less than zero or greater than the maximum value, treat it as not being a power of three.
        if (n < 0 || n > Integer.MAX_VALUE) {
            return false;
        }

        // Base case: 1 is the base power for 3, so if n equals 1 then it's a power of three!
        if (n == 1) {
            return true;
        }

        // Recursive step: check if n can be divided evenly by 3, if it can divide perfectly, then call isPowerOfThree() on n/3 and return true. If not, return false.
        return (n % 3 == 0 && isPowerOfThree(n / 3));
    }
}
```

